/* Pixel Passport visual system. The existing local data model and actions stay intact. */
const artRoot='/assets/';
const paintedCells={home:0,trips:1,packing:1,map:2,compass:2,tasks:3,budget:4,coins:4,bookings:5,tickets:5,ski:6,journal:7,settings:8,plane:9,train:10,camera:11,jacket:12,pants:13,thermals:14,sweater:14,boots:15,gloves:16,goggles:17,helmet:18,toiletries:19,electronics:20,passport:21,bottle:22,adapter:23,suitcase:1};
const pixelIcon=(name,extra='')=>paintedCells[name]===undefined?`<img class="pixel-icon ${extra}" src="${artRoot}icons/${name}.svg" alt="" aria-hidden="true">`:`<span class="painted-icon ${extra}" aria-hidden="true" style="background-position:${paintedCells[name]%6/5*100}% ${Math.floor(paintedCells[name]/6)/3*100}%"></span>`;
const pose=(n=0,extra='')=>`<span class="avatar-pose pose-${n} ${extra}" role="img" aria-label="Pixel travel companion"></span>`;
const actionPose=(n=0)=>`<span class="action-pose pose-${n}" role="img" aria-label="Traveler action pose"></span>`;
const viewPose=(n=0)=>`<span class="view-pose view-${n}" role="img" aria-label="Traveler turnaround view"></span>`;
const postcardFor=name=>/paris|france/i.test(name)?'paris':/st\.?\s*gallen|switzerland/i.test(name)?'st-gallen':/rome|italy/i.test(name)?'rome':/austria|vienna/i.test(name)?'atlas-austria':/finland|helsinki/i.test(name)?'finland':/athens|greece/i.test(name)?'atlas-greece':/venice/i.test(name)?'atlas-venice':null;
const postcard=(name,extra='')=>{const file=postcardFor(name);return file?.startsWith('atlas-')?`<div class="postcard atlas-postcard ${file} ${extra}" role="img" aria-label="Pixel art of ${esc(name)}"></div>`:file?`<img class="postcard ${extra}" src="${artRoot}destinations/${file}.webp" alt="Pixel art of ${esc(name)}">`:`<div class="postcard illustrated-alpine-fallback ${extra}" role="img" aria-label="Illustrated Alpine landscape"></div>`};
const section=(title,sub,action,label)=>`<div class="section-head"><div><div class="mini-rule"></div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action?`<button class="btn small primary" data-action="${action}">${label}</button>`:''}</div>`;
const tinyEmpty=(title,body,action,label,ico='compass')=>`<div class="storybook-empty">${pixelIcon(ico)}<strong>${title}</strong><p>${body}</p>${action?`<button class="btn small" data-action="${action}">${label}</button>`:''}</div>`;

const bannerCopy={
  trips:['The itinerary book','Gather every stop, stay, and little discovery in one place.','paris'],
  map:['The adventure atlas','Pin the places you dream of, and trace the journey as it grows.','st-gallen'],
  packing:['The packing room','A place for the practical things that make the magic possible.','st-gallen'],
  tasks:['The quest board','One small step at a time, the journey takes shape.','paris'],
  budget:['The travel ledger','Keep a thoughtful eye on every coin of the adventure.','rome'],
  bookings:['The booking vault','Tickets, stays, and confirmations for the road ahead.','paris'],
  ski:['Into the mountains','Fresh snow and winding trails are waiting for you.','st-gallen'],
  journal:['Pages from the road','Collect the little moments worth remembering.','rome'],
  settings:['Make it yours','Your traveler profile, preferences, and saved memories.','st-gallen']
};
const navAssets={home:'home',trips:'trips',map:'map',packing:'packing',tasks:'tasks',budget:'budget',bookings:'bookings',ski:'ski',journal:'journal',settings:'settings','style-guide':'star'};

function addBanner(main){const data=bannerCopy[page];if(!data)return;const node=document.createElement('section');node.className=`page-banner page-banner-${page}`;node.innerHTML=`<div class="page-banner-art" style="background-image:url('${artRoot}destinations/${data[2]}.webp')"></div><div class="page-banner-copy"><div class="eyebrow">PIXEL PASSPORT · ${page.toUpperCase()}</div><h2>${data[0]}</h2><p>${data[1]}</p></div><span class="page-banner-stamp">${pixelIcon(page==='ski'?'snow':navAssets[page])}</span>`;main.querySelector('.topbar').after(node)}

function decorateCards(){
  if(page==='packing'||page==='tasks')document.querySelector('.main>.grid.three')?.classList.add('compact-summary');
  const staticHeadings={'Stay & transport':'home','Expenses & notes':'budget','Weather':'cloud','Exchange rates':'budget','Traveler profile':'passport','Your data':'journal','Connected services':'settings','Accessibility':'settings','Saved places':'map','Passport collection':'passport'};
  document.querySelectorAll('.card h3').forEach(h=>{const text=h.textContent.replace(/^[\p{Extended_Pictographic}\uFE0F\u200D\s]+/u,'').trim();if(staticHeadings[text])h.innerHTML=`${pixelIcon(staticHeadings[text])} ${esc(text)}`});
  document.querySelectorAll('.destination-card').forEach(card=>{const name=card.querySelector('h3')?.textContent||'';const target=card.querySelector('.art');if(target){target.innerHTML=postcard(name);target.classList.add('has-postcard')}});
  if(page==='trips'){
    const cards=[...document.querySelectorAll('.destination-card')];
    cards.forEach(card=>{const did=card.querySelector('[data-action="openDestination"]')?.dataset.id;if(!did)return;card.draggable=true;card.dataset.destinationId=did;card.addEventListener('dragstart',event=>{event.dataTransfer?.setData('text/plain',did);card.classList.add('dragging')});card.addEventListener('dragend',()=>card.classList.remove('dragging'));card.addEventListener('dragover',event=>{event.preventDefault();card.classList.add('drag-over')});card.addEventListener('dragleave',()=>card.classList.remove('drag-over'));card.addEventListener('drop',event=>{event.preventDefault();card.classList.remove('drag-over');const from=event.dataTransfer?.getData('text/plain');if(!from||from===did)return;const route=state.destinations.filter(d=>d.tripId===selectedTrip).sort((a,b)=>a.order-b.order);const source=route.findIndex(d=>d.id===from),target=route.findIndex(d=>d.id===did);if(source<0||target<0)return;route.splice(target,0,...route.splice(source,1));route.forEach((d,i)=>d.order=i);save();toast('Route reordered')})});
    const toolbar=document.querySelector('.main>.toolbar');if(toolbar&&cards.length>1)toolbar.insertAdjacentHTML('afterend','<p class="drag-hint">Drag postcards to reorder your route, or use the arrow buttons on each stop.</p>');
  }
  document.querySelectorAll('.trip-card').forEach((card,i)=>{const name=card.querySelector('h3')?.textContent||'';const strip=document.createElement('div');strip.className='trip-cover';strip.style.backgroundImage=`url('${artRoot}${/family/i.test(name)?'destinations/st-gallen.webp':'landscapes/alpine-train.webp'}')`;card.prepend(strip)});
  document.querySelectorAll('.inventory-slot').forEach(slot=>{const label=slot.querySelector('strong')?.textContent?.toLowerCase()||'';let icon='suitcase';for(const [test,asset] of [[/passport/,'passport'],[/jacket|coat/,'jacket'],[/pant|jean/,'pants'],[/thermal|layer/,'thermals'],[/shoe|boot/,'boots'],[/glove/,'gloves'],[/goggle/,'goggles'],[/helmet/,'helmet'],[/bottle/,'bottle'],[/adapter|charger/,'adapter'],[/tooth|skin|sun|shampoo|toiletr/,'toiletries'],[/laptop|camera|phone/,'electronics']])if(test.test(label)){icon=asset;break}const e=slot.querySelector('.emoji');if(e)e.innerHTML=pixelIcon(icon)});
  document.querySelectorAll('.suggestion').forEach((card,i)=>{const title=card.querySelector('strong');const label=title?.textContent?.toLowerCase()||'';if(title)title.textContent=title.textContent.replace(/^[\p{Extended_Pictographic}\uFE0F\u200D\s]+/u,'');const icon=/ski|snow|glove|goggle/.test(label)?'ski':/transport|flight|train/.test(label)?'train':page==='packing'?'suitcase':'star';card.insertAdjacentHTML('afterbegin',pixelIcon(icon,'suggestion-icon'))});
  if(page==='tasks'){document.querySelectorAll('.quest').forEach(card=>{const priority=card.querySelector('.pill')?.textContent||'';const heading=card.querySelector('h3');heading?.insertAdjacentHTML('afterend',`<div class="quest-kind">${/high/i.test(priority)?'MAIN QUEST':'SIDE QUEST'} · +25 XP</div>`)});const stats=document.querySelector('.main>.grid.three');if(stats)stats.insertAdjacentHTML('afterend',`<div class="quest-companion">${pose(state.tasks.some(t=>t.done)?5:2)}<p>${state.tasks.some(t=>t.done)?'Every finished quest is a step closer to your adventure!':'Big adventures begin with one little quest.'}</p></div>`)}
  document.querySelectorAll('.journal-page').forEach(card=>{if(!card.querySelector('img'))card.insertAdjacentHTML('afterbegin',`<div class="journal-art">${pixelIcon('camera')}</div>`)});
  document.querySelectorAll('.stamp').forEach(stamp=>{const span=stamp.querySelector('span');if(span)span.innerHTML=pixelIcon('stamp')});
  if(page==='journal'){const stamps=[...new Set(state.destinations.filter(d=>d.status==='visited').map(d=>d.country))];const grid=document.querySelector('.stamp-grid');if(grid){const earned=[['First footprint',stamps.length>=1,'Visit your first country'],['Curious explorer',stamps.length>=3,'Visit three countries'],['Quest keeper',state.tasks.filter(t=>t.done).length>=5,'Complete five quests']];grid.insertAdjacentHTML('afterend',`<div class="achievement-row">${earned.map(([name,done,desc])=>`<div class="achievement ${done?'earned':'locked'}">${pixelIcon(done?'star':'stamp')}<strong>${name}</strong><small>${desc}</small></div>`).join('')}</div>`)}}
  if(page==='ski'){document.querySelectorAll('.snow-banner').forEach(b=>{b.style.backgroundImage=`linear-gradient(90deg,rgba(31,53,65,.72),rgba(31,53,65,.05)),url('${artRoot}skiing/alpine-resort.webp')`})}
  if(page==='map'){const mapShell=document.querySelector('.map-shell');mapShell?.classList.add('storybook-map');const canvas=document.querySelector('#map-canvas');if(canvas){const pins=new MutationObserver(()=>{canvas.querySelectorAll('.map-pin:not([data-illustrated])').forEach(pin=>{pin.dataset.status=({'💜':'wishlist','💚':'planned','💗':'booked','⭐':'visited'})[pin.textContent]||'planned';pin.dataset.illustrated='true';window.PPReact.renderWidget(pin,'AnimatedMapPin',{status:pin.dataset.status});const d=state.destinations.find(d=>`${d.name}, ${d.country}`===pin.title);if(d){pin.dataset.destinationId=d.id;pin.setAttribute('aria-label',`View ${d.name}, ${d.country}`);pin.onclick=event=>{event.stopPropagation();showMapPlace(d.id)}}})});pins.observe(canvas,{subtree:true,childList:true})};document.querySelectorAll('.legend b').forEach((b,i)=>b.innerHTML=`<span class="legend-pin legend-pin-${i}" aria-hidden="true"></span>`)}
  if(page==='bookings')document.querySelectorAll('.grid.three>.card').forEach(card=>{const name=card.querySelector('h3')?.textContent||'';const art=document.createElement('div');art.className='booking-art';art.innerHTML=pixelIcon(/train/i.test(card.textContent)?'train':/flight/i.test(card.textContent)?'plane':'hotel');card.prepend(art)});
  if(page==='budget'){const stats=document.querySelector('.main>.grid.four');if(stats){const base=state.profile.baseCurrency,budget=Number(state.profile.exchangeBudget)||0,actual=convertedExpenses().sum;const grouped=Object.entries(state.expenses.filter(e=>e.kind==='actual').reduce((out,e)=>{const city=destName(e.destinationId),value=expenseBase(e);if(value!=null)out[city]=(out[city]||0)+value;return out},{})).sort((a,b)=>b[1]-a[1]);const panel=document.createElement('div');panel.className='ledger-insights';panel.innerHTML=`<div class="paper-panel remaining-panel"><div class="panel-heading">${pixelIcon('budget')} <span>Remaining budget</span></div><strong>${budget?money(budget-actual,base):'Set a budget'}</strong><p>${budget?'Budget less recorded actual expenses':'Set your exchange budget to see what remains.'}</p></div><div class="paper-panel city-spending-panel"><div class="panel-heading">${pixelIcon('pin')} <span>Expenses by destination</span></div>${grouped.length?grouped.slice(0,4).map(([city,amount])=>`<div class="city-spending-row"><span>${esc(city)}</span><b>${money(amount,base)}</b></div>`).join(''):'<p>No destination expenses recorded yet.</p>'}</div>`;stats.after(panel)}}
  if(page==='ski')document.querySelectorAll('.grid.three>.card').forEach(card=>{const art=document.createElement('div');art.className='resort-art';card.prepend(art)});
  if(page==='trips'&&selectedDestination){const d=state.destinations.find(x=>x.id===selectedDestination);const detail=[...document.querySelectorAll('.section-head')].find(x=>x.textContent.includes('details'));if(d&&detail){const cover=document.createElement('div');cover.className='destination-detail-cover';cover.innerHTML=`${postcard(d.name)}<div><span class="eyebrow">DESTINATION JOURNAL</span><strong>${esc(d.name)}, ${esc(d.country)}</strong><small>${date(d.arrival)} — ${date(d.departure)}</small></div>`;detail.before(cover)}}
  const emptyConfig={bookings:['Your tickets belong here','Add your first reservation when the details are ready.','newBooking','Add a booking',0],ski:['A mountain day awaits','Save a resort and start preparing for the snow.','newSki','Plan a ski adventure',2],journal:['Your first story awaits','Collect a little memory from the road.','newJournal','Write a memory',4]};if(emptyConfig[page]){const empty=document.querySelector('.main>.grid>.empty');if(empty){const [title,copy,action,label,cell]=emptyConfig[page];empty.classList.add('illustrated-page-empty');empty.innerHTML=`${actionPose(cell)}<div><h3>${title}</h3><p>${copy}</p><button type="button" class="btn primary">${label}</button></div>`;empty.querySelector('button').onclick=()=>actions[action]?.({})}}
}

function showMapPlace(did){const d=state.destinations.find(d=>d.id===did),container=document.querySelector('.map-shell');if(!d||!container)return;map?.flyTo({center:[Number(d.lng),Number(d.lat)],zoom:Math.max(map.getZoom(),5),duration:matchMedia('(prefers-reduced-motion: reduce)').matches||state.profile.ambientMotion==='off'?0:600});container.querySelector('.map-place-sheet')?.remove();document.querySelectorAll('.map-pin').forEach(pin=>pin.classList.toggle('selected',pin.dataset.destinationId===did));const panel=document.createElement('section');panel.className='map-place-sheet';panel.setAttribute('aria-label',`${d.name} destination details`);panel.innerHTML=`<button type="button" class="sheet-close" aria-label="Close destination details">×</button>${postcard(d.name)}<div class="map-place-copy"><span class="pill ${d.status==='wishlist'?'lav':d.status==='booked'?'pink':''}">${esc(d.status)}</span><h3>${esc(d.name)}</h3><p>${esc(d.country)} · ${date(d.arrival)}</p><small>${esc(tripName(d.tripId))}</small><button type="button" class="btn primary sheet-open">Open itinerary →</button></div>`;container.append(panel);panel.querySelector('.sheet-close').onclick=()=>panel.remove();panel.querySelector('.sheet-open').onclick=()=>window.openMapDestination(did)}
actions.focusMap=({id})=>showMapPlace(id);
actions.openDestination=({id})=>{selectedDestination=id;render();setTimeout(()=>{const cover=document.querySelector('.destination-detail-cover');if(!cover)return;const root=document.documentElement,previous=root.style.scrollBehavior;root.style.scrollBehavior='auto';cover.scrollIntoView({behavior:'auto',block:'start'});root.style.scrollBehavior=previous},80)};
window.openMapDestination=did=>{selectedTrip=state.destinations.find(d=>d.id===did)?.tripId;go('trips');actions.openDestination({id:did})};
const originalInitMap=initMap;
initMap=function(){originalInitMap();if(map)map.once('error',()=>{const node=document.querySelector('.map-shell');if(node&&!node.querySelector('.map-network-note')){const note=document.createElement('div');note.className='map-network-note';note.textContent='Map tiles are taking longer to load. Your saved pins and places are still available.';node.append(note)}})};

window.pixelPassportEnhance=function(){
  document.body.dataset.page=page;
  if(page!=='home'&&homeMiniMap){homeMiniMap.remove();homeMiniMap=null}
  const main=document.querySelector('.main');if(!main)return;
  const brand=document.querySelector('.brand-mark');if(brand)brand.innerHTML=pixelIcon('compass');
  document.querySelectorAll('[data-nav]').forEach(button=>{const image=button.querySelector('.nav-icon');if(image)image.innerHTML=pixelIcon(navAssets[button.dataset.nav]||'star')});
  const label=document.querySelector('.sidebar-label');if(label)label.textContent='THE ADVENTURE BOOK';
  const xpCard=document.querySelector('.sidebar-bottom');if(xpCard){const sprite=xpCard.querySelector('.sidebar-sprite');if(sprite)sprite.outerHTML=pose(0,'sidebar-avatar')}
  const top=document.querySelector('.topbar .eyebrow');if(top)top.textContent='A LITTLE WORLD OF BIG ADVENTURES';
  const avatar=document.querySelector('.avatar-chip');if(avatar)avatar.innerHTML=pose(1,'chip-avatar');
  const mode=document.querySelector('.mode-chip');if(mode)mode.innerHTML=`${pixelIcon('heart')} Saved on this device`;
  if(page!=='home'&&page!=='style-guide'&&page!=='ski')addBanner(main);
  decorateCards();
  const phoneNav=document.createElement('nav');phoneNav.className='phone-nav';phoneNav.setAttribute('aria-label','Main navigation');phoneNav.innerHTML=[['home','Home','home'],['trips','Trips','trips'],['map','Map','map'],['packing','Packing','packing'],['more','More','settings']].map(([key,label,icon])=>`<button type="button" data-phone-nav="${key}" class="${page===key||(key==='more'&&!['home','trips','map','packing'].includes(page))?'active':''}" ${page===key?'aria-current="page"':''}>${pixelIcon(icon)}<span>${label}</span></button>`).join('');document.querySelector('.app').append(phoneNav);phoneNav.querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.phoneNav==='more'?document.querySelector('#sidebar').classList.toggle('open'):go(b.dataset.phoneNav));const scrim=document.createElement('button');scrim.className='phone-menu-scrim';scrim.type='button';scrim.setAttribute('aria-label','Close navigation menu');scrim.onclick=()=>document.querySelector('#sidebar').classList.remove('open');document.querySelector('.app').append(scrim);
  if(page==='home'){window.PPReact.renderDashboard(document.querySelector('#react-dashboard'),{data:{name:state.profile.name,nextTrip:nextTrip(),homeBase:state.destinations.find(d=>/st\.?\s*gallen/i.test(d.name))||state.destinations[0],destinations:state.destinations.filter(d=>d.status!=='visited').sort((a,b)=>(Number(a.status==='wishlist')-Number(b.status==='wishlist'))||(a.arrival||'9999').localeCompare(b.arrival||'9999')),planned:state.destinations.filter(d=>d.status!=='wishlist').length,totalDestinations:state.destinations.length,packing:state.packing,packed:packed(),totalPacking:state.packing.length,packPercent:pct(packed(),state.packing.length),completedTasks:state.tasks.filter(t=>t.done).length,totalTasks:state.tasks.length,pendingTasks:state.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')),progress:progressSummary(),actual:convertedExpenses().sum,budget:Number(state.profile.exchangeBudget)||0,baseCurrency:state.profile.baseCurrency,bookings:state.bookings.filter(b=>!b.date||days(b.date)>=0),skiTrips:state.skiTrips,stamps:[...new Set(state.destinations.filter(d=>d.status==='visited').map(d=>d.country))]},onAction:action=>actions[action]?.({}),onDestination:did=>{selectedTrip=state.destinations.find(d=>d.id===did)?.tripId;go('trips');actions.openDestination({id:did})}});setTimeout(initHomeMiniMap,0)}
};

let homeMiniMap=null;
function initHomeMiniMap(){const node=document.querySelector('#home-mini-map');if(homeMiniMap){homeMiniMap.remove();homeMiniMap=null}if(!node||!window.maplibregl)return;try{homeMiniMap=new maplibregl.Map({container:node,interactive:false,attributionControl:false,style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256}},layers:[{id:'osm',type:'raster',source:'osm'}]},center:[13.4,48.6],zoom:2.9});homeMiniMap.once('style.load',()=>{state.destinations.filter(d=>Number.isFinite(Number(d.lat))&&Number.isFinite(Number(d.lng))).forEach(d=>{const el=document.createElement('span');el.className='mini-map-pin';el.title=`${d.name}, ${d.country}`;new maplibregl.Marker({element:el}).setLngLat([Number(d.lng),Number(d.lat)]).addTo(homeMiniMap)})})}catch{node.innerHTML=`<div class="map-fallback">${pixelIcon('map')}<p>Your saved places are in the World Map.</p></div>`}}

window.pixelPassportDesignPage=function(){
  const iconNames=['home','trips','map','packing','tasks','budget','bookings','ski','journal','settings','plane','train','bus','ferry','suitcase','passport','camera','compass','hotel','calendar','pin','jacket','sweater','thermals','pants','boots','gloves','goggles','helmet','toiletries','electronics','bottle','adapter','flower','star','mountain','stamp','cat','food','heart','clock','snow','cloud'];
  const colors=[['Cream','#fff7e8'],['Parchment','#f3e6d0'],['Sage','#a9be9a'],['Forest green','#526e58'],['Dusty rose','#e7b0ac'],['Peach','#f2c6a5'],['Sky blue','#b9d9e8'],['Lavender','#c9c0e5'],['Warm brown','#443b35']];
  return `<section class="design-hero"><div><div class="eyebrow">THE MAKING OF AN ADVENTURE</div><h2>Pixel Passport<br>style guide</h2><p>A small library of storybook colors, places, characters, and useful little details.</p></div>${pose(0)}</section>
  ${section('The color story','Warm paper and pastel scenery, anchored by ink and sage.')}<div class="swatch-grid">${colors.map(([name,value])=>`<div class="swatch"><i style="background:${value}"></i><strong>${name}</strong><small>${value}</small></div>`).join('')}</div>
  ${section('The type','Fraunces tells the story. Nunito keeps the details clear. Pixel lettering marks the small delights.')}<div class="type-grid"><div class="paper-panel"><div class="eyebrow">A LITTLE ADVENTURE</div><h2 class="type-display">Where to next?</h2><p>Every journey begins with a curious thought and a well-worn map.</p></div><div class="paper-panel"><span class="pixel-sample">PIXEL PASSPORT</span><p>Pixel accents are reserved for labels, chapter markers, and playful stamps.</p></div></div>
  ${section('Traveler companion','Expressions, outfits, actions, and turnaround views in reusable sprite sheets.')}<div class="sprite-gallery">${['Happy','Excited','Thinking','Walking','Tired','Celebrating'].map((name,i)=>`<div class="sprite-tile">${pose(i)}<span>${name}</span></div>`).join('')}</div><div class="outfit-gallery">${['Explorer','Skiing','Summer','City','Rainy','Hiking'].map((name,i)=>`<div class="sprite-tile"><span class="outfit-pose outfit-${i}" role="img" aria-label="${name} outfit"></span><span>${name}</span></div>`).join('')}</div><div class="sprite-gallery">${['Luggage','Walking','Map reading','Photography','Planning','Waving'].map((name,i)=>`<div class="sprite-tile">${actionPose(i)}<span>${name}</span></div>`).join('')}</div><div class="view-gallery">${['Front','Side','Back','Three-quarter'].map((name,i)=>`<div class="sprite-tile">${viewPose(i)}<span>${name}</span></div>`).join('')}</div>
  ${section('Places to dream of','Original pixel postcards for the journey.')}<div class="postcard-gallery">${['Paris','St. Gallen','Rome','Vienna','Helsinki','Athens','Venice'].map(name=>`<figure>${postcard(name)}<figcaption>${name}</figcaption></figure>`).join('')}</div>
  ${section('Handmade icon set','Designed as crisp, scalable SVG pixel art.')}<div class="icon-gallery">${iconNames.map(name=>`<div>${pixelIcon(name)}<small>${name}</small></div>`).join('')}</div>
  ${section('Useful little pieces','Controls and components used throughout the app.')}<div class="component-gallery"><div class="paper-panel"><h3>Button styles</h3><div class="row wrap"><span class="btn primary">Primary action</span><span class="btn pink">Special action</span><span class="btn ghost">Quiet action</span></div></div><div class="paper-panel"><h3>Progress & status</h3><div class="progress"><span style="width:68%"></span></div><div class="row wrap" style="margin-top:18px"><span class="pill">Planned</span><span class="pill pink">Booked</span><span class="pill yellow">Wishlist</span></div></div></div>`;
};

if(!nav.some(n=>n[0]==='style-guide'))nav.push(['style-guide','Style Guide','star']);
header=(title,sub,button,action)=>`<div class="section-head"><div><h2>${pixelIcon(navAssets[page]||'compass')} ${title.replace(/^[\p{Extended_Pictographic}\uFE0F\u200D\s]+/u,'')}</h2>${sub?`<p>${sub}</p>`:''}</div>${button?`<button class="btn small primary" data-action="${action}">${button}</button>`:''}</div>`;
homePage=()=>'<div id="react-dashboard"></div>';
// Living-world integration performs the initial render.
